#!/usr/bin/env python3
import json, sys
OUT=sys.argv[1]; s=json.load(open(OUT+'/SUMMARY.json')); L=[]; A=L.append; mb=lambda b: f"{b/1e6:.1f} MB"
A('# Dropbox outside `Github/`: byte-identity crosswalk, 25 October 2026\n')
A('Data only. Scientific effect NONE. Credit 0. Completes the Dropbox side of the retroactive accounting that `audits/dropbox_import/2026-10-24` (main#594, the `Github/` subtree) began, with the same indexes and the same `content_hash` rule; it creates no second catalog.\n')
A('## Scope and inputs\n')
A(f"- {s['scope']}.")
f=s['files']; A(f"- **Files:** {f['total']:,} in all; {f['hashed']:,} with a `content_hash` read from link metadata (no file downloaded); {f['counted_only_personal_or_other_material']} personal or other-material files counted only (link files, personal documents, an app bundle, the owner's other research); {f['empty']} empty; {f['pending_hash']} without a hash.")
A("- **Reference sides.** The 32,221 fetched Git blobs of main and Math- (Dropbox `content_hash` per blob), the two reassembled archives (DG-MIGRATION object `a2136bc0`, git blob `c4065c67`), and the 5,724 `Github/` hashes of main#594. Tiers: `GIT_EXACT`, `ARCHIVE_EXACT`, `GITHUB_TREE_COPY` (same bytes as a `Github/` file), `ROOT_DUP` (same bytes as another file outside `Github/` only), `ROOT_ONLY` (found nowhere else).\n")
A('## Tiers\n'); A('| tier | files | files in published parts | bytes of published parts (rounded to 100 KB) |\n|---|---:|---:|---:|')
for t,v in s['tiers'].items(): A(f"| `{t}` | {v['files']:,} | {v['files_in_published_parts']:,} | {mb(v['bytes_rounded_published_parts'])} |")
A(f"\n{s['tier_bytes_rule'][0].upper()+s['tier_bytes_rule'][1:]}.\n")
gw=s['git_exact_where']; A(f"`GIT_EXACT` by location: {', '.join(f'{k} {v}' for k,v in sorted(gw.items()) if k)}. {s['github_tree_overlap']['files_byte_identical_to_a_Github_file']} hashed files are byte-identical to a `Github/` file (so already covered by main#594's tiers).\n")
ro=s['root_only']; A(f"**Found nowhere else (`ROOT_ONLY`):** {ro['files']} files, {ro['distinct_contents']} distinct contents, by folder label {', '.join(f'{k} {v}' for k,v in sorted(ro['by_folder'].items()))}; by class {', '.join(f'{k} {v}' for k,v in sorted(ro['by_class'].items()))}. `ROOT_DUP`: {s['root_dup']['files']} files, {s['root_dup']['distinct_contents']} distinct contents.\n")
A('## Folders (synthetic labels; the label-to-folder map is local)\n'); A('| label | files | hashed | years with three or more files (omitted where the folder has per-file rows) |\n|---|---:|---:|---|')
for k,v in sorted(s['by_folder'].items()): A(f"| {k} | {v['files']} | {v['hashed']} | {', '.join(v['years']) or '(omitted)'} |")
A(f"\n{s['by_folder_rule'][0].upper()+s['by_folder_rule'][1:]}.")
lg=s['ledger']; A(f"\n## Coverage ledger\n\nThe main#594 name rule applied to the paths below each folder gives {lg['name_hits']} hits over {lg['rows_hit']} of the 344 ledger units ({len(lg['missing_proof_rows_hit'])} `MISSING`-proof units: rows {', '.join(map(str,lg['missing_proof_rows_hit'])) or 'none'}); by class {', '.join(f'{k} {v}' for k,v in sorted(lg['hits_by_match'].items()))}; by tier of the hit item {', '.join(f'{k} {v}' for k,v in sorted(lg['hits_by_tier'].items()))}. Name evidence only. Published hits cover only items in the `GIT_EXACT`, `ARCHIVE_EXACT` and `GITHUB_TREE_COPY` tiers ({lg['hits_on_other_tiers_kept_local']} hit on other items stays local, as do the matched tokens, which are fragments of Dropbox names); `LEDGER_ROOT.tsv` is one line per unit, `LEDGER_ROOT_ROWS.tsv` lists only hits on bytes-public items with the match class and no tokens.\n")
A('## Files\n')
A(f"- `ROOT_CROSSWALK.tsv`: {s['row_level_rows']} per-file rows, all for bytes already public (`GIT_EXACT`, `ARCHIVE_EXACT`): folder label, class, bytes, `content_hash`, tier, Git blob or archive locator, ledger rows. No Dropbox path, name or time.")
A(f"- `ROOT_AGGREGATE.tsv`: the {s['aggregate_files']:,} other files by folder label, tier and class; classes below three files are merged into `(other)` per folder and tier, and a cell still below three prints its count only.")
A('- `LEDGER_ROOT.tsv`, `LEDGER_ROOT_ROWS.tsv`, `SUMMARY.json` (with the hash receipt), `PINS.json` (inputs and local files by hash), `own/` (the scripts, local roots replaced).\n')
A('## Limits\n')
A('- Byte identity says a file is preserved somewhere; it says nothing about canonical copies, review status or correctness. The `Github/` tiers of main#594 are not repeated here.')
A('- The hash receipt ties each `content_hash` to the listing by path and byte count only; the connector returns no revision with link metadata, so a same-size edit between the listing and the hash read is not excluded.')
A('- Files and folders are counted and labelled, never named; the labels are synthetic and the label-to-folder map, the path-level inventory and the hashes stay local with the author and are offered to the owner or the CoS.')
A('- Not checked here: the `Github/` subtree itself (main#594), files changed after the listing, and the content of the counted-only files.')
open(OUT+'/README.md','w',encoding='utf-8').write('\n'.join(L)+'\n'); print('readme',len('\n'.join(L)),'bytes')
